-- 1. sınıf soru bankası: bağlamı soru köküne taşıma (2026-10-25, B1 bölümü)
-- Kaynak: docs/soru-uretim/paket/soru_paketi_1sinif_db_2026-10-24.json ; plan: DUZELTME_PLANI_BAGLAM_2026-10-24.md
-- Yalnız soru_metni, ipuclari, cozum_adimlari, yanlis_sik_geri_bildirimi güncellenir. Şıklar, doğru şık, onay durumu DEĞİŞMEZ.
-- Beklenen: 26 satır güncellenir; başka satıra dokunmaz (dis_soru_id eşleşmesi).
with d(dis_soru_id, soru_metni, ipuclari, cozum_adimlari, yanlis) as (values
  ('tr1-21', $t$Şu cümleye bak: “bugün hava çok güzel.” Bu cümlede hangi yazım yanlışı vardır?$t$, $j$["Cümleyi baştan sona dikkatle incele."]$j$::jsonb, $j$["Cümleler büyük harfle başlar.","Yukarıdaki cümle küçük harfle başlıyor; sonunda nokta var ve sözcükler ayrı yazılmış.","Doğru cevap A seçeneğidir."]$j$::jsonb, $j${"B":"Nokta unutulabilir; ama cümlenin sonunda nokta vardır.","C":"Bitişik yazım hatası olabilir; ama sözcükler ayrı yazılmıştır.","D":"Her sözcüğün büyük harfle başlaması gerektiği sanılabilir; ama yalnızca cümlenin ilk sözcüğü büyük harfle başlar."}$j$::jsonb),
  ('tr1-22', $t$Şu cümlenin sonuna işaret konmamış: “Bugün okula gelecek misin” Cümlenin sonuna hangi işaret konmalıdır?$t$, $j$["Cümlenin ne anlatmak için kurulduğunu düşün."]$j$::jsonb, $j$["Cümle, bir kişiye bir şey soruyor.","Soru anlamı taşıyan cümlenin sonuna soru işareti konur.","Doğru cevap B seçeneğidir."]$j$::jsonb, $j${"A":"Çoğu cümlenin sonuna nokta konduğu için çekici gelir; ama bu cümle soru cümlesidir.","C":"Ünlem sevinç veya şaşkınlıkta kullanılır; bu cümle öyle değildir.","D":"Virgül cümle içinde kullanılır; cümlenin sonuna konmaz."}$j$::jsonb),
  ('tr1-23', $t$Şu cümleye bak: “Dün akşam ayşe bize geldi.” Bu cümlede hangi sözcüğün ilk harfi büyük yazılmalıdır?$t$, $j$["Kişilere verilen adlar nasıl yazılır, düşün."]$j$::jsonb, $j$["Cümlenin ilk sözcüğü zaten büyük harfle başlıyor.","Kişi adları büyük harfle başlar; cümledeki kişi adı ayşe sözcüğüdür.","Doğru cevap C seçeneğidir."]$j$::jsonb, $j${"A":"Zaman bildirdiği için önemli görünür; ama akşam sözcüğü her zaman küçük yazılır.","B":"Cümlenin ortasındaki sözcüktür; ama bize kişi adı değildir.","D":"Cümlenin sonundaki sözcük olduğu için büyük yazılmak istenebilir; ama kişi adı değildir."}$j$::jsonb),
  ('tr1-24', $t$Şu cümlenin sonuna işaret konmamış: “Ne güzel bir resim yaptın” Bu cümle sevinç anlatıyor. Sonuna hangi işaret konmalıdır?$t$, $j$["Duygu anlatan cümlelerin sonuna hangi işaretin konduğunu hatırla."]$j$::jsonb, $j$["Cümle bir soru sormuyor; sevinç ve şaşkınlık anlatıyor.","Sevinç, şaşkınlık gibi duyguları anlatan cümlelerin sonuna ünlem işareti konur.","Doğru cevap D seçeneğidir."]$j$::jsonb, $j${"A":"Çoğu cümlenin sonuna nokta konduğu için çekici gelir; ama bu cümle duygu anlatır.","B":"Cümle ne sözcüğüyle başladığı için soru gibi görünür; ama bu cümle soru sormaz.","C":"Virgül cümle içinde kullanılır; cümlenin sonuna konmaz."}$j$::jsonb),
  ('mat1-01', $t$Ali’nin çantasında on dört kalem var. Kalem sayısı rakamlarla nasıl yazılır?$t$, $j$["Sayının adını yavaşça söyle ve duyduğun parçaları düşün."]$j$::jsonb, $j$["Sayının adı \"on dört\" olarak verilmiş.","On dört, rakamlarla 14 diye yazılır.","Doğru cevap A seçeneğidir."]$j$::jsonb, $j${"B":"Rakamların yerini ters yazma hatası (14 yerine 41).","C":"Sayının adındaki yalnız \"on\" kısmını yazıp \"dört\" kısmını unutma.","D":"Sayıyı bir eksik sayma hatası (14 yerine 13)."}$j$::jsonb),
  ('mat1-02', $t$Masanın üstünde 3 kırmızı ve 4 mavi balon var. Masanın üstünde toplam kaç balon var?$t$, $j$["Balonları renklerine göre gruplara ayır ve her grubu ayrı düşün."]$j$::jsonb, $j$["Kırmızı balonlar 3 tanedir.","Mavi balonlar 4 tanedir.","3 ve 4 balon birleşince 3 + 4 = 7 balon olur.","Doğru cevap B seçeneğidir."]$j$::jsonb, $j${"A":"Yalnız kırmızı balonları sayıp mavi grubu hesaba katmama.","C":"Balonlardan birini saymayı unutma (sayarken bir tane atlama).","D":"Balonlardan birini iki kez sayma."}$j$::jsonb),
  ('mat1-03', $t$Kuyrukta bekleyen çocuklardan Ali baştan ikinci sırada, Ayşe ise Ali'nin hemen arkasında. Ayşe baştan kaçıncı sıradadır?$t$, $j$["Kuyruğu baştan başlayarak çocukları sırayla say."]$j$::jsonb, $j$["Ali baştan ikinci sıradadır.","Ayşe, Ali'nin hemen arkasındadır; yani ikinciden sonra gelir.","İkinciden sonraki sıra üçüncüdür.","Doğru cevap C seçeneğidir."]$j$::jsonb, $j${"A":"Kuyruğun başındaki çocuk sanıp birinci sırayı seçme.","B":"Ayşe'yi Ali ile karıştırıp Ali'nin sırasını yazma.","D":"Kuyruğun sonundaki sırayı seçme."}$j$::jsonb),
  ('mat1-04', $t$Ali'nin 9 kalemi, Ayşe'nin 7 kalemi var. Aşağıdakilerden hangisi doğrudur?$t$, $j$["Sayarken hangi sayıyı daha sonra söylediğine bak."]$j$::jsonb, $j$["Ali'nin 9 kalemi, Ayşe'nin 7 kalemi var.","Sayarken 9, 7'den sonra gelir; yani 9 daha büyüktür.","Bu yüzden Ali'nin kalemi daha çoktur.","Doğru cevap D seçeneğidir."]$j$::jsonb, $j${"A":"Küçük sayıyı büyük sanıp iki kişiyi ters karşılaştırma.","B":"\"Daha az\" ve \"daha çok\" terimlerini karıştırma.","C":"İki sayı birbirine yakın olduğu için eşit sanma."}$j$::jsonb),
  ('mat1-05', $t$Ayşe onar onar sayıyor: 10, 20, 30, 40. Ayşe'nin söyleyeceği sıradaki sayı kaçtır?$t$, $j$["Sayıların her adımda ne kadar arttığına bak."]$j$::jsonb, $j$["Ayşe onar onar sayıyor: 10, 20, 30, 40.","Her adımda sayı 10 artıyor.","40'tan sonra gelen sayı 40 + 10 = 50 olur.","Doğru cevap A seçeneğidir."]$j$::jsonb, $j${"B":"Onar sayma yerine birer birer sayıp 40'a 1 ekleme.","C":"Ritmi karıştırıp 40'a 5 ekleme.","D":"Bir adımı atlayıp 50 yerine bir sonraki onluğu söyleme."}$j$::jsonb),
  ('mat1-06', $t$Ali kartlara sırayla 10, 8, 6, 4 sayılarını yazdı. Aynı kuralla devam edersek sıradaki kartta hangi sayı olur?$t$, $j$["Sayıların her adımda nasıl değiştiğine dikkat et."]$j$::jsonb, $j$["Sayılar 10, 8, 6, 4 diye gidiyor.","Her adımda sayı 2 azalıyor.","4'ten sonra 4 - 2 = 2 gelir.","Doğru cevap B seçeneğidir."]$j$::jsonb, $j${"A":"Kuralı birer birer azalma sanıp 4'ten 1 çıkarma.","C":"Geriye doğru değil ileriye bakıp bir önceki sayıyı yazma.","D":"Kuralı sürdürmeyip son sayıyı tekrar etme."}$j$::jsonb),
  ('mat1-07', $t$Bir kavanozun tam yarısı bilyelerle dolu ve içinde 4 bilye var. Kavanoz tamamen dolarsa içinde kaç bilye olur?$t$, $j$["Dolu kısım ile kavanozun tamamı arasındaki ilişkiyi düşün."]$j$::jsonb, $j$["Kavanozun yarısında 4 bilye var.","Diğer yarısı da aynı kadar bilye alır.","Tamamı 4 + 4 = 8 bilye olur.","Doğru cevap C seçeneğidir."]$j$::jsonb, $j${"A":"Yarıdaki sayıyı kavanozun tamamı sanma.","B":"Yarıdaki sayıya ilişkiyi kullanmadan rastgele 2 ekleme.","D":"Yarıyı büyütmek yerine ikiye bölme."}$j$::jsonb),
  ('mat1-09', $t$Ali'nin 15 bilyesi vardı. Ali 4 bilyesini arkadaşına verdi. Ali'nin geriye kaç bilyesi kaldı?$t$, $j$["Ali bilyesini verince elindeki bilye sayısı artar mı, azalır mı?"]$j$::jsonb, $j$["Ali'nin önce 15 bilyesi vardı.","Arkadaşına 4 bilye verdi; bilye sayısı azaldı.","15 - 4 = 11 olur.","Doğru cevap A seçeneğidir."]$j$::jsonb, $j${"B":"Verme durumunda çıkarma yerine toplama yapma (15 + 4).","C":"Geriye doğru sayarken bir fazla sayma.","D":"Geriye doğru sayarken bir eksik sayma."}$j$::jsonb),
  ('mat1-10', $t$Ali 6 + 6 = 12 olduğunu biliyor. 6 + 7 işleminin sonucu kaçtır?$t$, $j$["Bildiğin işlemden başla; ikinci sayının nasıl değiştiğine bak."]$j$::jsonb, $j$["Ali 6 + 6 = 12 olduğunu biliyor.","6 + 7 işleminde ikinci sayı 6'dan 1 fazladır.","Bu yüzden sonuç 12'den 1 fazladır: 12 + 1 = 13.","Doğru cevap B seçeneğidir."]$j$::jsonb, $j${"A":"İkinci sayıdaki farkı hesaba katmayıp bilinen sonucu aynen yazma.","C":"7 + 7 işlemiyle karıştırma.","D":"6 + 5 işlemiyle karıştırıp farkı ters yöne uygulama."}$j$::jsonb),
  ('mat1-11', $t$Ali tahtaya 9 + 3 = 8 + ? yazıyor. Eşitliğin doğru olması için ? yerine hangi sayı gelmelidir?$t$, $j$["Eşit işaretinin iki yanı aynı değerde olmalıdır."]$j$::jsonb, $j$["Eşit işaretinin sol tarafı 9 + 3 = 12 eder.","Sağ taraf da 12 olmalıdır: 8 + ? = 12.","8'e 4 eklenince 12 olur; ? yerine 4 gelir.","Doğru cevap C seçeneğidir."]$j$::jsonb, $j${"A":"Soldaki 3 sayısını görüp aynen yazma.","B":"Eksik sayıyı bulurken sayarken bir fazla ekleme.","D":"Soldaki 9 ile sağdaki 8 arasındaki farkı yazma."}$j$::jsonb),
  ('mat1-12', $t$Ali tahtaya 8 + 6 = 14 yazıyor. Buna göre sonucu 8 olan çıkarma işlemi hangisidir?$t$, $j$["Toplama işlemindeki sayıların çıkarmada nasıl kullanıldığını düşün."]$j$::jsonb, $j$["8 + 6 = 14 olduğuna göre toplamdan bir parça çıkarılırsa diğer parça kalır.","14'ten 6 çıkarılırsa 8 kalır: 14 - 6 = 8.","Diğer seçeneklerin sonuçları 6, 2 ve 20 olur.","Doğru cevap D seçeneğidir."]$j$::jsonb, $j${"A":"Toplamdan 8'i çıkarınca 6 kaldığını fark etmeme; sonucu 8 sanma.","B":"Toplamı hiç kullanmayıp kartta geçen sayıları sırayla çıkarma.","C":"Çıkarma yerine toplama işlemini seçme."}$j$::jsonb),
  ('mat1-13', $t$Ali'nin cüzdanında bir 20 TL, bir 10 TL ve bir 5 TL var. Ali'nin toplam kaç TL'si vardır?$t$, $j$["Her paranın değerini ayrı ayrı düşün, sonra birleştir."]$j$::jsonb, $j$["Paraların değerleri 20 TL, 10 TL ve 5 TL'dir.","Önce 20 + 10 = 30 TL olur.","Sonra 30 + 5 = 35 TL olur.","Doğru cevap A seçeneğidir."]$j$::jsonb, $j${"B":"5 TL'lik parayı hesaba katmama.","C":"5 TL'lik parayı 10 TL sanma.","D":"10 TL'lik parayı hesaba katmama (20 + 5)."}$j$::jsonb),
  ('mat1-14', $t$Sınıf oylamasında elma 6 oy, portakal 3 oy, muz 4 oy aldı. Elma, portakaldan kaç oy fazla almıştır?$t$, $j$["Önce elmanın ve portakalın oy sayılarını bul."]$j$::jsonb, $j$["Elma 6 oy aldı.","Portakal 3 oy aldı.","Aradaki fark 6 - 3 = 3 oydur.","Doğru cevap B seçeneğidir."]$j$::jsonb, $j${"A":"Portakal yerine muzu alıp farkı 6 - 4 = 2 sanma.","C":"Elmanın oy sayısını cevap sanıp farkı hesaplamama.","D":"Farkı bulmak yerine iki oy sayısını toplama (6 + 3)."}$j$::jsonb),
  ('hb1-01', $t$Yeni bir arkadaşla tanışırken önce adımızı söyleriz. Sonra hangi sınıfta olduğunu sorarız. Parçaya göre, yeni bir arkadaşla tanışırken önce ne yaparız?$t$, $j$["Parçada \"önce\" sözcüğünün yanında yazan işe bak."]$j$::jsonb, $j$["Parçaya göre tanışırken ilk iş adımızı söylemektir.","Soru da tanışırken önce ne yapıldığını soruyor.","Kendi adımızı söylemek bu işe uyar.","Doğru cevap A seçeneğidir."]$j$::jsonb, $j${"B":"Karşıdakini tanımak için soru sormak akla gelir ama parçada bu iş ilk değil, sonra yapılan iştir.","C":"Oyun önermek arkadaşça görünür ama tanışmanın ilk adımı değildir.","D":"Bir şey göstermek paylaşmak gibi görünür ama parçadaki ilk iş bu değildir."}$j$::jsonb),
  ('hb1-02', $t$Sınıfta konuşmak için parmak kaldırırız. Arkadaşımız konuşurken onu dinleriz. Parçaya göre, sınıfta konuşmak isteyen bir öğrenci ne yapmalıdır?$t$, $j$["Parçanın ilk cümlesinde konuşmak için yapılan şey yazıyor."]$j$::jsonb, $j$["Parça, sınıfta konuşmak için ne yaptığımızı söylüyor.","Bu iş parmak kaldırmaktır.","Parmak kaldırıp beklemek kurala uyar.","Doğru cevap B seçeneğidir."]$j$::jsonb, $j${"A":"Hemen konuşmak istenince akla gelir ama parçaya göre arkadaşı dinlemek gerekir.","C":"Yerinden kalkmak dikkat çekmek için yapılır ama konuşmak için gereken iş değildir.","D":"Bağırmak sesini duyurmak için yapılır ama parçadaki kurala uymaz."}$j$::jsonb),
  ('hb1-04', $t$Yaya ışığı kırmızıyken kaldırımda bekleriz. Yeşil yanınca sağımıza ve soluma bakıp karşıya geçeriz. Parçaya göre, yaya ışığı kırmızıyken ne yaparız?$t$, $j$["Parçada kırmızı ışık yanarken yapılan iş yazıyor."]$j$::jsonb, $j$["Soru, yaya ışığı kırmızıyken ne yapıldığını soruyor.","Parçaya göre kırmızıyken kaldırımda bekleriz.","Kaldırımda durup beklemek bu cümleye uyar.","Doğru cevap D seçeneğidir."]$j$::jsonb, $j${"A":"Koşarak geçmek vakit kazandırır gibi görünür ama kırmızıyken beklemek gerekir.","B":"Yola çıkıp izlemek dikkatli olmak gibi görünür ama kırmızıyken yola çıkılmaz.","C":"Araba görünmeyince geçmek kolay gelir ama kırmızıyken beklemek gerekir."}$j$::jsonb),
  ('hb1-05', $t$Bir çocuk ailesini anlatıyor: “Evde annem, babam, ablam, kardeşim ve ben varız.” Bu ailede toplam kaç kişi vardır?$t$, $j$["Konuşan çocuk da ailenin bir üyesidir. Parçadaki herkesi say."]$j$::jsonb, $j$["Parçadaki kişileri sayalım: annem, babam, ablam, kardeşim ve ben.","Bir, iki, üç, dört, beş eder.","Aile beş kişidir.","Doğru cevap A seçeneğidir."]$j$::jsonb, $j${"B":"Konuşan çocuk kendini saymazsa dört bulur.","C":"Bir kişiyi iki kez sayınca altı çıkar.","D":"Yalnızca anne, baba ve bir kardeşi sayınca üç çıkar."}$j$::jsonb),
  ('hb1-06', $t$Bizim evde herkesin bir işi var. Annem sofrayı kurar, babam yemek yapar, ablam çöpü çıkarır. Bu evde ablanın işi nedir?$t$, $j$["Parçanın ikinci cümlesinde her kişinin yanında bir iş yazıyor. Ablanın adını ara."]$j$::jsonb, $j$["Parça, evdeki herkesin işini sayıyor.","Annem sofrayı kurar, babam yemek yapar.","Ablanın işi çöpü çıkarmaktır.","Doğru cevap B seçeneğidir."]$j$::jsonb, $j${"A":"Sofrayı kurmak parçada geçer ama bu işi anne yapar.","C":"Yemek yapmak parçada geçer ama bu işi baba yapar.","D":"Bulaşık yıkamak evde yapılan bir iştir ama parçada ablanın işi olarak yazmaz."}$j$::jsonb),
  ('hb1-07', $t$İstanbul, ülkemizin en kalabalık şehridir ama ülkemizin başkenti Ankara'dır. Parçaya göre, ülkemizin başkenti hangi şehirdir?$t$, $j$["Parçada iki şehir geçiyor. Başkentin hangisi olduğu \"ama\" sözcüğünden sonra yazıyor."]$j$::jsonb, $j$["Parçada İstanbul'un kalabalık bir şehir olduğu yazıyor.","Başkent olan şehir ise \"ama\" sözcüğünden sonra söyleniyor.","Ülkemizin başkenti Ankara'dır.","Doğru cevap C seçeneğidir."]$j$::jsonb, $j${"A":"İstanbul parçada ilk geçen ve en kalabalık şehirdir, bu yüzden başkent sanılabilir.","B":"İzmir büyük ve bilinen bir şehirdir, bu yüzden akla gelebilir.","D":"Bursa büyük ve bilinen bir şehirdir, bu yüzden akla gelebilir."}$j$::jsonb),
  ('hb1-08', $t$Güneş, Dünya ve Ay'ı göstermek için bir model yapılıyor: Güneş bir basketbol topu, Dünya bir bilye, Ay ise bir bezelyedir. Bu modele göre hangi cümle doğrudur?$t$, $j$["Modeldeki üç şeyin büyüklüğünü sırayla karşılaştır."]$j$::jsonb, $j$["Modelde Güneş basketbol topu, Dünya bilye, Ay bezelyedir.","En büyük basketbol topu, sonra bilye, en küçük bezelyedir.","Bilye bezelyeden büyüktür, yani Dünya Ay'dan büyüktür.","Doğru cevap D seçeneğidir."]$j$::jsonb, $j${"A":"Ay ile Dünya'nın sırası ters söylenmiştir; bezelye bilyeden küçüktür.","B":"Dünya ile Güneş'in sırası ters söylenmiştir; bilye basketbol topundan küçüktür.","C":"Ay ile Güneş'in sırası ters söylenmiştir; bezelye basketbol topundan küçüktür."}$j$::jsonb),
  ('hb1-09', $t$Bir çocuk saksıya toprak koyup tohum ekti ve her gün suladı. Tohumun neden büyüdüğünü merak ediyor. Çocuk merak ettiğini öğrenmek için hangi soruyu sormalıdır?$t$, $j$["Çocuğun neyi merak ettiği parçanın sonunda yazıyor. Soru o merakı sormalı."]$j$::jsonb, $j$["Parça, çocuğun tohumun neden büyüdüğünü merak ettiğini söylüyor.","Merak edileni öğrenmek için tam bunu soran soru gerekir.","\"Tohum neden büyür?\" sorusu bu merakı sorar.","Doğru cevap A seçeneğidir."]$j$::jsonb, $j${"B":"Toprak konusu parçada geçer ama çocuk toprağın kim tarafından hazırlandığını merak etmiyor.","C":"Tohum hakkında bir sorudur ama çocuk tohumun rengini merak etmiyor.","D":"Ekme işiyle ilgili bir sorudur ama çocuk saksının nereden alındığını merak etmiyor."}$j$::jsonb),
  ('hb1-10', $t$Evde bir robot süpürge çalışıyor. Bir çocuk onun yolunu nasıl bulduğunu merak ediyor. Çocuk merak ettiğini öğrenmek için hangi soruyu sormalıdır?$t$, $j$["Çocuğun neyi merak ettiği parçanın sonunda yazıyor. Soru o merakı sormalı."]$j$::jsonb, $j$["Parça, çocuğun robot süpürgenin yolunu nasıl bulduğunu merak ettiğini söylüyor.","Merak edileni öğrenmek için tam bunu soran soru gerekir.","\"Süpürge yolunu nasıl bulur?\" sorusu bu merakı sorar.","Doğru cevap B seçeneğidir."]$j$::jsonb, $j${"A":"Robot süpürge hakkında bir sorudur ama çocuk fiyatını merak etmiyor.","C":"Robot süpürge hakkında bir sorudur ama çocuk rengini merak etmiyor.","D":"Robot süpürge hakkında bir sorudur ama çocuk onu kimin yaptığını merak etmiyor."}$j$::jsonb)
),
upd as (
update public.questions q
   set soru_metni = d.soru_metni,
       ipuclari = d.ipuclari,
       cozum_adimlari = d.cozum_adimlari,
       yanlis_sik_geri_bildirimi = d.yanlis
  from d
 where q.dis_soru_id = d.dis_soru_id
   and q.uretim_partisi = 'soru-uretim-2026-10-24-1sinif'
returning q.dis_soru_id)
select count(*) as guncellenen from upd;
